(()=>{let r=document.querySelectorAll(".file-wrap");if(!r.length)return;r.forEach((i)=>{let e=i.querySelector('input[type="file"]'),n=i.querySelector(".file-name");if(!e||!n)return;n.setAttribute("aria-live","polite");let l=()=>{let{files:t}=e;n.textContent=t&&t.length?t.length>1?`${t.length} filer valda`:t[0].name:"Ingen fil vald"};if(e.addEventListener("change",l),e.form)e.form.addEventListener("reset",()=>setTimeout(l,0));l()})})();
